def subterms(value):
    out=[]
    todo=[value]
    while todo:
        item=todo.pop()
        if isinstance(item,list) and item:
            out.append(item)
            i=1
            while i<len(item):
                if isinstance(item[i],list):
                    todo.append(item[i])
                i+=1
    return out

def has_tag(value,name):
    for item in subterms(value):
        if item[0]==name:
            return True
    return False

def unique(values):
    out=[]
    for value in values:
        if value not in out:
            out.append(value)
    return out

def collect_entries(premises):
    nodes=premises.get('nodes',[])
    roots=premises.get('roots',[])
    byid={}
    for node in nodes:
        byid[node.get('id')]=node
    out=[]
    for root in roots:
        todo=[root]
        seen=set()
        while todo:
            nid=todo.pop()
            if nid in seen or nid not in byid:
                continue
            seen.add(nid)
            node=byid[nid]
            for term in subterms(node.get('term')):
                out.append((term,root))
            for child in node.get('child_ids',[]):
                todo.append(child)
    return out

def role_tags(value,definitions):
    tags=set()
    todo=[value]
    seen=set()
    while todo:
        item=todo.pop()
        if not isinstance(item,list) or not item:
            continue
        name=item[0]
        if name=='source_recipient_role_of' and len(item)>2:
            tags.add(str(item[2]))
        elif name=='employees_of' or name=='internal_personnel_of':
            tags.add('employees')
        elif name=='independent_contractors_of':
            tags.add('contractors')
        elif name=='consultants_of':
            tags.add('consultants')
        elif name=='agents_of':
            tags.add('agents')
        elif name=='professional_advisors_of':
            tags.add('professional_advisers')
        elif name=='legal_advisors_of':
            tags.add('legal_advisers')
        elif name=='financial_advisors_of':
            tags.add('financial_advisers')
        elif name=='accountants_of':
            tags.add('accountants')
        elif name=='lenders_of':
            tags.add('lenders')
        elif name=='third_parties':
            tags.add('third_parties')
        elif name=='representatives_of' and len(item)>1:
            key=str(item[1])
            if key not in seen:
                seen.add(key)
                for owner,members in definitions:
                    if str(owner)==key or (isinstance(owner,list) and owner and owner[0]=='party'):
                        todo.append(members)
        i=1
        while i<len(item):
            if isinstance(item[i],list):
                todo.append(item[i])
            i+=1
    return tags

def apply(inputs,premises):
    task=inputs.get('task_id')
    if task not in ('nda-5','nda-7','nda-16','nda-20'):
        return {'handled':False,'answer':None,'used_nodes':[]}
    entries=collect_entries(premises)
    if task in ('nda-5','nda-7'):
        definitions=[]
        definition_roots=[]
        absence=[]
        permissions=[]
        prohibitions=[]
        relevant=[]
        for term,root in entries:
            if term[0]=='define_representative' and len(term)==3:
                definitions.append((term[1],term[2]))
                definition_roots.append(root)
            elif term[0]=='complete_source_no_disclosure_permission':
                absence.append(root)
        for term,root in entries:
            if term[0] not in ('permission','prohibition') or len(term)<3:
                continue
            action=term[2]
            if not isinstance(action,list) or len(action)!=3 or action[0]!='disclose' or not has_tag(action[1],'confidential_information'):
                continue
            relevant.append(root)
            tags=role_tags(action[2],definitions)
            if term[0]=='permission':
                permissions.append((root,tags,action[2]))
            else:
                prohibitions.append((root,tags,action[2]))
        wanted={'employees'} if task=='nda-5' else {'contractors','consultants','agents','professional_advisers','legal_advisers','financial_advisers','accountants','lenders','third_parties'}
        for root,tags,recipient in permissions:
            if tags.intersection(wanted):
                used=[root]
                if has_tag(recipient,'representatives_of'):
                    used.extend(definition_roots)
                return {'handled':True,'answer':'Entailment','used_nodes':unique(used)}
        for root,tags,recipient in prohibitions:
            if has_tag(recipient,'outsiders_to'):
                continue
            if tags.intersection(wanted):
                return {'handled':True,'answer':'Contradiction','used_nodes':[root]}
        if relevant or absence:
            return {'handled':True,'answer':'NotMentioned','used_nodes':unique(relevant+definition_roots+absence)}
        return {'handled':False,'answer':None,'used_nodes':[]}
    disposal=[]
    retention_yes=[]
    retention_no=[]
    no_disposal=[]
    no_retention=[]
    for term,root in entries:
        if term[0]=='disposal_obligation' and len(term)==5:
            disposal.append((term,root))
        elif term[0] in ('retention_permission','retention_exception'):
            retention_yes.append(root)
        elif term[0]=='retention_prohibition':
            retention_no.append(root)
        elif term[0]=='complete_source_no_disposal_obligation':
            no_disposal.append(root)
        elif term[0]=='complete_source_no_retention_effect':
            no_retention.append(root)
    if task=='nda-16':
        relevant=[]
        entailed=[]
        for term,root in disposal:
            action=term[2]
            trigger=term[3]
            if not (has_tag(action,'return_to') or has_tag(action,'destroy')):
                continue
            relevant.append(root)
            if has_tag(trigger,'agreement_termination') or has_tag(trigger,'service_termination') or has_tag(trigger,'relationship_termination'):
                entailed.append(root)
        if entailed:
            return {'handled':True,'answer':'Entailment','used_nodes':unique(entailed)}
        if relevant or no_disposal:
            return {'handled':True,'answer':'NotMentioned','used_nodes':unique(relevant+no_disposal)}
        return {'handled':False,'answer':None,'used_nodes':[]}
    if retention_yes:
        return {'handled':True,'answer':'Entailment','used_nodes':unique(retention_yes)}
    if retention_no:
        return {'handled':True,'answer':'Contradiction','used_nodes':unique(retention_no)}
    relevant=[]
    for term,root in disposal:
        if has_tag(term[2],'return_to') or has_tag(term[2],'destroy'):
            relevant.append(root)
    if relevant or no_retention or no_disposal:
        return {'handled':True,'answer':'NotMentioned','used_nodes':unique(relevant+no_retention+no_disposal)}
    return {'handled':False,'answer':None,'used_nodes':[]}

