def answer_rows(value):
    if isinstance(value,list):
        return value
    if isinstance(value,dict):
        answers=value.get('answers')
        if isinstance(answers,list):
            return answers
        if isinstance(answers,dict):
            return list(answers.values())
        return list(value.values())
    return []

def answered_ids(rows):
    out=set()
    for row in rows:
        if isinstance(row,dict) and isinstance(row.get('id'),str):
            out.add(row.get('id'))
    return out

def answer_for(rows,qid):
    for row in rows:
        if isinstance(row,dict) and row.get('id')==qid:
            return row
    return None

def evidence_ids(answer):
    out=[]
    if not isinstance(answer,dict):
        return out
    evidence=answer.get('evidence',[])
    if isinstance(evidence,dict):
        evidence=[evidence]
    for item in evidence:
        if isinstance(item,dict):
            uid=item.get('unit_id')
            if uid not in out:
                out.append(uid)
    return out

def apply(inputs,premises):
    spans=inputs.get('source_spans',[])
    rows=answer_rows(inputs.get('semantic_answers',[]))
    answered=answered_ids(rows)
    all_units=[]
    for span in spans:
        all_units.append(span.get('id'))
    queries=[]
    initial=[('disclosure_scout_v3_complete','operative_disclosure_clause_scout_v3'),('scout_disposal_complete','disposal_obligation_scout'),('retention_permission_v3_complete','retention_permission_scout_v3'),('retention_prohibition_v3_complete','retention_prohibition_scout_v3')]
    for qid,operation in initial:
        if qid not in answered:
            queries.append({'id':qid,'operation':operation,'unit_ids':all_units})
    if queries:
        return {'queries':queries}
    disclosure=answer_for(rows,'disclosure_scout_v3_complete')
    if isinstance(disclosure,dict) and disclosure.get('choice')=='candidate_found':
        window=evidence_ids(disclosure)
        details=[('disclosure_modality_v3','disclosure_modality_v3'),('disclosure_employee_v3','disclosure_employee_role_v3'),('disclosure_contractor_v3','disclosure_contractor_role_v3'),('disclosure_consultant_v3','disclosure_consultant_role_v3'),('disclosure_agent_v3','disclosure_agent_role_v3'),('disclosure_professional_adviser_v3','disclosure_professional_adviser_role_v3'),('disclosure_legal_adviser_v3','disclosure_legal_adviser_role_v3'),('disclosure_financial_adviser_v3','disclosure_financial_adviser_role_v3'),('disclosure_accountant_v3','disclosure_accountant_role_v3'),('disclosure_need_v3','disclosure_need_v3'),('disclosure_extent_v3','disclosure_extent_v3'),('disclosure_safeguard_v3','disclosure_safeguard_v3')]
        if window:
            for qid,operation in details:
                if qid not in answered:
                    queries.append({'id':qid,'operation':operation,'unit_ids':window})
    disposal=answer_for(rows,'scout_disposal_complete')
    if isinstance(disposal,dict) and disposal.get('choice')=='candidate_found':
        prefix=[]
        for uid in evidence_ids(disposal):
            prefix.append(uid)
            qid='disposal_'+str(uid)
            if qid not in answered:
                queries.append({'id':qid,'operation':'disposal_pattern','unit_ids':list(prefix)})
    return {'queries':queries}
